insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('riego-por-goteo-casero-para-espacios-pequenos','agricultura',array['ambiente']::text[],'Riego por goteo casero para espacios pequeños','Construye un sistema simple de goteo con botellas, mangueras o cintas de tela para regar unas macetas, y comprueba si el agua llega de forma pareja y si ahorra tiempo.','Prototipo','3 semanas',20,array['Riego por goteo','Prototipo casero']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria agricola agronomia ingenieria ambiental ingenieria civil ingenieria sanitaria estadistica ingenieria de sistemas fisica diseno de prototipos. medicion. resolucion de problemas. documentacion tecnica. botellas o mangueras reutilizadas. jarra medidora. cuaderno de registro.',$a23agr${"id": "riego-por-goteo-casero-para-espacios-pequenos", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Riego por goteo casero para espacios pequeños", "resumen": "Construye un sistema simple de goteo con botellas, mangueras o cintas de tela para regar unas macetas, y comprueba si el agua llega de forma pareja y si ahorra tiempo.", "tipo": "Prototipo", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Riego por goteo", "Prototipo casero"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agrícola", "Agronomía", "Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Sanitaria", "Estadística", "Ingeniería de Sistemas", "Física"], "problema": ["El riego por goteo entrega agua poco a poco y reduce el desperdicio, pero los equipos comerciales pueden ser costosos para un huerto de balcón. Los sistemas caseros existen, aunque a veces se tapan, gotean demasiado o riegan de manera desigual.", "Diseñar y probar uno propio permite entender cómo funciona y adaptarlo al espacio."], "desarrollar": ["Dibuja un esquema del sistema y elige materiales reutilizados, como botellas perforadas o mangueras finas. Construye el prototipo para tres o cuatro macetas y llénalo con agua limpia.", "Mide cuánta agua sale por cada punto en el mismo tiempo y comprueba si es pareja. Ajusta el diseño y vuelve a medir. Escribe una ficha con los materiales, el esquema, los problemas que aparecieron y las mejoras."], "ampliaciones": [{"titulo": "Con temporizador", "aporta": "piensa cómo automatizarlo con un temporizador sencillo."}, {"titulo": "Comparar con riego manual", "aporta": "mide el ahorro de agua frente a regar con regadera."}, {"titulo": "Guía para armarlo", "aporta": "escribe instrucciones ilustradas para que otros lo construyan."}], "objetivos": ["Diseñar un esquema.", "Construir el prototipo.", "Medir la uniformidad.", "Documentar mejoras."], "habilidades": ["Diseño de prototipos.", "Medición.", "Resolución de problemas.", "Documentación técnica."], "herramientas": ["Botellas o mangueras reutilizadas.", "Jarra medidora.", "Cuaderno de registro."], "lineamientos": ["Si usas agua de lluvia o reutilizada, riega solo el suelo y no las hojas de lo que vayas a comer, y lava bien lo que coseches.", "Verifica que el sistema no gotee sobre cables, equipos o vecinos.", "Usa materiales limpios y seguros para el contacto con plantas comestibles."], "otroSector": "El mismo diseño de distribución pareja sirve para repartir cualquier recurso, como insumos, tareas o energía."}$a23agr$::jsonb,30),
('donde-se-pierde-el-agua-al-regar-y-como-ahorrarla','agricultura',array['ambiente']::text[],'¿Dónde se pierde el agua al regar y cómo ahorrarla?','Mide cuánta agua se pierde por evaporación, escurrimiento o exceso al regar, y compara prácticas como regar de mañana, cubrir el suelo o regar despacio para encontrar las que más ahorran.','Análisis','3 semanas',18,array['Pérdidas de agua','Ahorro']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria agricola agronomia ingenieria ambiental ingenieria civil ingenieria sanitaria estadistica ingenieria de sistemas fisica medicion de volumenes. comparacion de practicas. analisis de datos. comunicacion. macetas y platos. jarra medidora. hoja de calculo.',$a24agr${"id": "donde-se-pierde-el-agua-al-regar-y-como-ahorrarla", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Dónde se pierde el agua al regar y cómo ahorrarla?", "resumen": "Mide cuánta agua se pierde por evaporación, escurrimiento o exceso al regar, y compara prácticas como regar de mañana, cubrir el suelo o regar despacio para encontrar las que más ahorran.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Pérdidas de agua", "Ahorro"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agrícola", "Agronomía", "Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Sanitaria", "Estadística", "Ingeniería de Sistemas", "Física"], "problema": ["Parte del agua que se echa a una planta nunca llega a las raíces: se evapora, se escurre por los bordes o sale por el fondo de la maceta. Como no se ve, rara vez se cuenta.", "Identificar dónde se pierde permite hacer pequeños cambios que ahorran agua sin gastar dinero."], "desarrollar": ["Prepara varias macetas iguales y riégalas de distintas maneras: regar rápido, regar despacio, regar con el suelo cubierto con hojas secas y regar a distinta hora. Recoge el agua que sale por el fondo y mide cuánta es en cada caso.", "Compara cuánta agua se pierde y cuánta se retiene. Elabora una lista de tres prácticas que ahorran agua según tus resultados, con una explicación sencilla de por qué funcionan."], "ampliaciones": [{"titulo": "Evaporación", "aporta": "mide cuánta agua se evapora de un recipiente abierto en un día soleado."}, {"titulo": "Tipo de suelo", "aporta": "compara la pérdida en distintos sustratos."}, {"titulo": "Metas de ahorro", "aporta": "estima cuánta agua ahorrarías en un mes si aplicas las prácticas."}], "objetivos": ["Medir el agua que se pierde.", "Comparar prácticas de riego.", "Identificar las que más ahorran.", "Explicar los resultados."], "habilidades": ["Medición de volúmenes.", "Comparación de prácticas.", "Análisis de datos.", "Comunicación."], "herramientas": ["Macetas y platos.", "Jarra medidora.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Si usas agua de lluvia o reutilizada, riega solo el suelo y no las hojas de lo que vayas a comer, y lava bien lo que coseches.", "No uses agua de dudosa calidad para plantas que vayas a consumir."], "otroSector": "El mismo análisis de dónde se pierde un recurso sirve para reducir mermas de tiempo, energía o materiales en cualquier proceso."}$a24agr$::jsonb,31),
('como-conservar-la-humedad-del-suelo','agricultura',array['ambiente']::text[],'Cómo conservar la humedad del suelo','Prueba si cubrir el suelo con hojas secas, paja o cáscaras ayuda a que la tierra se mantenga húmeda más tiempo, y compara cuántos días tarda en secarse cada macetero.','Análisis','3 semanas',18,array['Humedad del suelo','Acolchado']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria agricola agronomia ingenieria ambiental ingenieria civil ingenieria sanitaria estadistica ingenieria de sistemas fisica control de variables. observacion diaria. registro de datos. analisis. macetas. hojas secas, paja o carton. un palillo para medir humedad.',$a25agr${"id": "como-conservar-la-humedad-del-suelo", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Cómo conservar la humedad del suelo", "resumen": "Prueba si cubrir el suelo con hojas secas, paja o cáscaras ayuda a que la tierra se mantenga húmeda más tiempo, y compara cuántos días tarda en secarse cada macetero.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Humedad del suelo", "Acolchado"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agrícola", "Agronomía", "Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Sanitaria", "Estadística", "Ingeniería de Sistemas", "Física"], "problema": ["La tierra expuesta al sol y al viento se seca rápido y obliga a regar más seguido. Hay prácticas antiguas, como cubrir el suelo con materia seca, que prometen mantener la humedad, pero pocas veces se miden.", "Comprobar cuánto ayudan permite ahorrar agua y tiempo con un gesto muy sencillo."], "desarrollar": ["Prepara varias macetas iguales con la misma tierra y planta. Deja una sin cobertura y cubre las otras con distintos materiales, como hojas secas, paja o cartón, en una capa de tres a cinco centímetros.", "Cada día revisa la humedad de la tierra a unos centímetros de profundidad y anota cuántos días tarda cada maceta en secarse. Compara en una tabla y concluye qué cobertura funcionó mejor."], "ampliaciones": [{"titulo": "Espesor de la capa", "aporta": "compara capas de distinto grosor."}, {"titulo": "Efecto en la planta", "aporta": "mide si el crecimiento también cambia."}, {"titulo": "Materiales disponibles", "aporta": "elabora una lista de coberturas económicas según la zona."}], "objetivos": ["Preparar macetas comparables.", "Medir la humedad.", "Comparar coberturas.", "Recomendar una práctica."], "habilidades": ["Control de variables.", "Observación diaria.", "Registro de datos.", "Análisis."], "herramientas": ["Macetas.", "Hojas secas, paja o cartón.", "Un palillo para medir humedad."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Usa coberturas limpias y secas, libres de hongos o de restos de productos químicos.", "Si usas agua de lluvia o reutilizada, riega solo el suelo y no las hojas de lo que vayas a comer, y lava bien lo que coseches."], "otroSector": "El mismo enfoque de reducir pérdidas con una barrera simple sirve para conservar frío, calor o humedad en otros usos."}$a25agr$::jsonb,32),
('agua-de-lluvia-para-regar-un-huerto','agricultura',array['ambiente']::text[],'Agua de lluvia para regar un huerto','Calcula cuánta agua de lluvia podría recoger un techo o un balcón y cuántas macetas podría regar con ella, usando datos públicos de precipitación y tus propias medidas.','Análisis','3 semanas',20,array['Agua de lluvia','Huerto']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria agricola agronomia ingenieria ambiental ingenieria civil ingenieria sanitaria estadistica ingenieria de sistemas fisica calculo de areas y volumenes. lectura de datos publicos. comparacion. diseno sencillo. datos publicos de precipitacion. hoja de calculo. cinta metrica.',$a26agr${"id": "agua-de-lluvia-para-regar-un-huerto", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Agua de lluvia para regar un huerto", "resumen": "Calcula cuánta agua de lluvia podría recoger un techo o un balcón y cuántas macetas podría regar con ella, usando datos públicos de precipitación y tus propias medidas.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Agua de lluvia", "Huerto"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Agrícola", "Agronomía", "Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Sanitaria", "Estadística", "Ingeniería de Sistemas", "Física"], "problema": ["En lugares donde llueve, mucha agua se va por el desagüe mientras se riega con agua potable. Aprovecharla puede ahorrar agua, pero antes conviene saber cuánto se puede captar y si alcanza para el huerto.", "Sin hacer las cuentas, es fácil construir un sistema que se queda corto o que sobra."], "desarrollar": ["Con datos públicos de precipitación de tu zona, estima cuánta lluvia cae al mes. Mide el área de un techo o superficie donde podrías captar el agua y calcula los litros que podrías recoger en un mes.", "Estima cuánta agua necesita tu huerto al mes y compara. Concluye si la lluvia alcanza, en qué meses sobra o falta, y qué tamaño de recipiente de almacenamiento necesitarías. Nota que en zonas muy secas el ejercicio servirá como comparación de escenarios."], "ampliaciones": [{"titulo": "Por mes", "aporta": "haz el cálculo mes a mes para ver cuándo conviene almacenar."}, {"titulo": "Almacenamiento", "aporta": "diseña un esquema de recolección y depósito."}, {"titulo": "Comparar zonas", "aporta": "calcula el mismo ejercicio para una zona más lluviosa y una más seca."}], "objetivos": ["Obtener datos de lluvia.", "Calcular el agua captable.", "Comparar con la demanda del huerto.", "Dimensionar el almacenamiento."], "habilidades": ["Cálculo de áreas y volúmenes.", "Lectura de datos públicos.", "Comparación.", "Diseño sencillo."], "herramientas": ["Datos públicos de precipitación.", "Hoja de cálculo.", "Cinta métrica."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Si usas agua de lluvia o reutilizada, riega solo el suelo y no las hojas de lo que vayas a comer, y lava bien lo que coseches.", "No almacenes agua sin tapa: puede criar mosquitos."], "otroSector": "El mismo cálculo de oferta y demanda sirve para dimensionar cualquier recurso que se capta y se usa, como la energía solar."}$a26agr$::jsonb,33),
('que-metodo-conserva-mejor-frutas-y-verduras','agricultura',array['ambiente']::text[],'¿Qué método conserva mejor frutas y verduras?','Compara cuánto duran las mismas frutas y verduras guardadas de distintas maneras, como en el frío, en envases cerrados, envueltas o a temperatura ambiente, y recomienda el método más conveniente.','Análisis','4 semanas',20,array['Conservación','Frutas y verduras']::text[],array['investigar']::text[],'propios',NULL,'ingenieria alimentaria ingenieria agroindustrial nutricion ingenieria quimica quimica biologia diseno administracion control de variables. observacion. registro fotografico. analisis. frutas y verduras. envases y bolsas. camara del celular.',$a27agr${"id": "que-metodo-conserva-mejor-frutas-y-verduras", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Qué método conserva mejor frutas y verduras?", "resumen": "Compara cuánto duran las mismas frutas y verduras guardadas de distintas maneras, como en el frío, en envases cerrados, envueltas o a temperatura ambiente, y recomienda el método más conveniente.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 20, "etiquetas": ["Conservación", "Frutas y verduras"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Alimentaria", "Ingeniería Agroindustrial", "Nutrición", "Ingeniería Química", "Química", "Biología", "Diseño", "Administración"], "problema": ["Mucha fruta y verdura se echa a perder en casa antes de ser consumida. Se guardan según costumbre, a veces en el lugar equivocado, sin saber si ese método realmente las conserva más tiempo.", "Comparar métodos con las mismas frutas y verduras permite saber cuál alarga más su vida útil."], "desarrollar": ["Elige una o dos frutas o verduras y divide cada una en porciones iguales. Guárdalas con tres o cuatro métodos distintos y anota la fecha de inicio. Revisa cada uno o dos días su aspecto, su firmeza y su olor, y toma fotos.", "Define de antemano cuándo consideras que algo ya no se debe consumir, por ejemplo cuando aparece moho. Compara cuánto duró cada método y recomienda el más conveniente."], "ampliaciones": [{"titulo": "Más alimentos", "aporta": "repite con otras frutas y verduras para ver si el resultado cambia."}, {"titulo": "Costo y esfuerzo", "aporta": "compara qué método es más barato y más práctico."}, {"titulo": "Tabla de duración", "aporta": "construye una tabla resumen que otros puedan usar."}], "objetivos": ["Preparar muestras comparables.", "Registrar su estado.", "Comparar la duración.", "Recomendar un método."], "habilidades": ["Control de variables.", "Observación.", "Registro fotográfico.", "Análisis."], "herramientas": ["Frutas y verduras.", "Envases y bolsas.", "Cámara del celular."], "lineamientos": ["No pruebes ni consumas alimentos que parezcan echados a perder; el objetivo es observar, no arriesgarse.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Descarta lo que muestre moho o mal olor; no lo pruebes para comprobar."], "otroSector": "El mismo método de comparar formas de almacenar sirve para decidir cómo guardar insumos o productos en cualquier negocio."}$a27agr$::jsonb,34),
('cuanto-duran-y-por-que-se-echan-a-perder-distintos-alimentos','agricultura',array['ambiente']::text[],'¿Cuánto duran y por qué se echan a perder distintos alimentos?','Observa cuánto tardan en deteriorarse alimentos comunes guardados en casa e identifica qué características, como la humedad o el tipo de alimento, hacen que unos duren más que otros.','Análisis','4 semanas',22,array['Vida útil','Deterioro de alimentos']::text[],array['investigar']::text[],'propios',NULL,'ingenieria alimentaria ingenieria agroindustrial nutricion ingenieria quimica quimica biologia diseno administracion observacion diaria. registro de datos. comparacion. explicacion de causas. alimentos de casa. cuaderno de registro. camara del celular.',$a28agr${"id": "cuanto-duran-y-por-que-se-echan-a-perder-distintos-alimentos", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Cuánto duran y por qué se echan a perder distintos alimentos?", "resumen": "Observa cuánto tardan en deteriorarse alimentos comunes guardados en casa e identifica qué características, como la humedad o el tipo de alimento, hacen que unos duren más que otros.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 22, "etiquetas": ["Vida útil", "Deterioro de alimentos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Alimentaria", "Ingeniería Agroindustrial", "Nutrición", "Ingeniería Química", "Química", "Biología", "Diseño", "Administración"], "problema": ["Algunos alimentos duran semanas y otros se echan a perder en dos días. Se suele atribuir a la suerte, pero influyen factores como el agua que contienen, el daño previo o cómo se guardan.", "Entender por qué se deterioran permite anticipar qué consumir primero y evitar desperdicios."], "desarrollar": ["Elige entre cinco y ocho alimentos comunes, como pan, tomate, plátano, zanahoria o papa, y guárdalos en condiciones iguales. Revisa a diario su aspecto y anota el día en que aparecen cambios claros, como moho, blandura o mal olor.", "Ordena los alimentos del que dura más al que dura menos y relaciona el orden con sus características, como cuánta agua tienen o si estaban maduros. Presenta un cuadro de duración y tu explicación de las diferencias."], "ampliaciones": [{"titulo": "Con y sin cáscara", "aporta": "compara el mismo alimento entero y cortado."}, {"titulo": "Alimento dañado", "aporta": "observa cómo se deteriora un alimento con golpes frente a uno sano."}, {"titulo": "Lista de prioridad", "aporta": "crea una lista de qué comer primero y qué puede esperar."}], "objetivos": ["Seleccionar alimentos.", "Registrar su deterioro.", "Ordenar por duración.", "Explicar las diferencias."], "habilidades": ["Observación diaria.", "Registro de datos.", "Comparación.", "Explicación de causas."], "herramientas": ["Alimentos de casa.", "Cuaderno de registro.", "Cámara del celular."], "lineamientos": ["No pruebes ni consumas alimentos que parezcan echados a perder; el objetivo es observar, no arriesgarse.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Mantén los alimentos en deterioro lejos de otros alimentos y de las mascotas."], "otroSector": "El mismo análisis de cuánto dura algo sirve para estudiar la vida útil de productos, materiales o insumos."}$a28agr$::jsonb,35),
('guia-para-guardar-bien-los-alimentos-en-casa','agricultura',array['salud']::text[],'Guía para guardar bien los alimentos en casa','Elabora una guía ilustrada que explique dónde y cómo guardar los alimentos más comunes del hogar para que duren más, apoyándote en recomendaciones públicas de instituciones de salud y alimentación.','Guía','2 semanas',14,array['Almacenamiento','Alimentos en casa']::text[],array['crear']::text[],'publicos',NULL,'nutricion ingenieria alimentaria educacion comunicaciones diseno ingenieria agroindustrial salud publica trabajo social busqueda de fuentes confiables. sintesis. diseno de informacion. comunicacion clara. guias publicas oficiales. un editor de documentos. iconos o dibujos.',$a29agr${"id": "guia-para-guardar-bien-los-alimentos-en-casa", "area": "agricultura", "areas2": ["salud"], "titulo": "Guía para guardar bien los alimentos en casa", "resumen": "Elabora una guía ilustrada que explique dónde y cómo guardar los alimentos más comunes del hogar para que duren más, apoyándote en recomendaciones públicas de instituciones de salud y alimentación.", "tipo": "Guía", "tiempo": "2 semanas", "horas": 14, "etiquetas": ["Almacenamiento", "Alimentos en casa"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Nutrición", "Ingeniería Alimentaria", "Educación", "Comunicaciones", "Diseño", "Ingeniería Agroindustrial", "Salud Pública", "Trabajo Social"], "problema": ["En muchos hogares se guardan los alimentos por costumbre: el pan en el refrigerador, la papa junto a la cebolla, las frutas todas juntas. Algunas costumbres ayudan y otras acortan la vida de los alimentos o los hacen menos seguros.", "Una guía clara con lo que dicen las fuentes oficiales ayuda a evitar pérdidas y a cuidar la inocuidad."], "desarrollar": ["Consulta guías públicas de instituciones de salud y alimentación sobre conservación en casa. Clasifica los alimentos por tipo y anota para cada grupo dónde conviene guardarlos, por cuánto tiempo y qué señales indican que ya no deben consumirse.", "Diseña una guía de una o dos páginas con tablas, iconos y consejos breves. Revísala con alguien de tu familia para ver si se entiende y ajusta el lenguaje."], "ampliaciones": [{"titulo": "Versión para el refrigerador", "aporta": "crea un cartel de una página para pegar en la cocina."}, {"titulo": "Mitos frecuentes", "aporta": "añade una sección con ideas comunes que no son ciertas."}, {"titulo": "Por temporada", "aporta": "adapta los consejos al calor o al frío de tu zona."}], "objetivos": ["Reunir recomendaciones oficiales.", "Clasificar los alimentos.", "Diseñar la guía.", "Revisarla con otra persona."], "habilidades": ["Búsqueda de fuentes confiables.", "Síntesis.", "Diseño de información.", "Comunicación clara."], "herramientas": ["Guías públicas oficiales.", "Un editor de documentos.", "Iconos o dibujos."], "lineamientos": ["No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Resume lo que dicen las fuentes oficiales sin cambiar el sentido y remite a ellas para dudas de seguridad alimentaria."], "otroSector": "La misma forma de convertir normas en una guía simple sirve para explicar procedimientos de seguridad en cualquier trabajo."}$a29agr$::jsonb,36),
('que-envase-conserva-mejor-frutas-y-verduras','agricultura',array[]::text[],'¿Qué envase conserva mejor frutas y verduras?','Compara cuánto duran las mismas frutas y verduras guardadas en distintos envases, como bolsa de plástico, caja de plástico, papel, tela y sin envase, y qué cambia en cada caso.','Análisis','4 semanas',20,array['Envases','Conservación']::text[],array['investigar']::text[],'propios',NULL,'ingenieria alimentaria ingenieria agroindustrial nutricion ingenieria quimica quimica biologia diseno administracion control de variables. observacion. registro de datos. analisis. envases de casa. frutas y verduras. hoja de calculo.',$a30agr${"id": "que-envase-conserva-mejor-frutas-y-verduras", "area": "agricultura", "areas2": [], "titulo": "¿Qué envase conserva mejor frutas y verduras?", "resumen": "Compara cuánto duran las mismas frutas y verduras guardadas en distintos envases, como bolsa de plástico, caja de plástico, papel, tela y sin envase, y qué cambia en cada caso.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 20, "etiquetas": ["Envases", "Conservación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Alimentaria", "Ingeniería Agroindustrial", "Nutrición", "Ingeniería Química", "Química", "Biología", "Diseño", "Administración"], "problema": ["El envase influye en cuánto dura un alimento fresco: algunos atrapan humedad y favorecen el moho, otros dejan escapar el agua y secan el producto. En casa se usa lo que hay a mano sin saber si es lo mejor.", "Comparar envases con datos permite elegir mejor y también reducir plásticos innecesarios."], "desarrollar": ["Selecciona una fruta o verdura y repártela en porciones iguales. Guárdalas en tres o cuatro envases distintos en el mismo lugar y con la misma temperatura. Revisa cada día la firmeza, el color, la humedad y la presencia de moho.", "Anota el día en que cada una deja de estar en buen estado. Compara la duración, el aspecto y el costo de cada envase, y concluye cuál conviene más y en qué casos."], "ampliaciones": [{"titulo": "Con aire y sin aire", "aporta": "compara envases cerrados y con orificios para ventilar."}, {"titulo": "Impacto ambiental", "aporta": "comenta qué envases se pueden reutilizar o reciclar."}, {"titulo": "Frutas distintas", "aporta": "repite con otro tipo de producto y compara los resultados."}], "objetivos": ["Preparar muestras iguales.", "Registrar el estado.", "Comparar envases.", "Recomendar según el caso."], "habilidades": ["Control de variables.", "Observación.", "Registro de datos.", "Análisis."], "herramientas": ["Envases de casa.", "Frutas y verduras.", "Hoja de cálculo."], "lineamientos": ["No pruebes ni consumas alimentos que parezcan echados a perder; el objetivo es observar, no arriesgarse.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Lava los envases antes de usarlos y no los reutilices si han contenido sustancias químicas."], "otroSector": "El mismo método de comparar envases sirve para decidir cómo empacar y proteger productos en negocios de cualquier tipo."}$a30agr$::jsonb,37),
('como-influye-la-temperatura-en-la-conservacion-de-los-alimentos','agricultura',array[]::text[],'¿Cómo influye la temperatura en la conservación de los alimentos?','Guarda los mismos alimentos a distintas temperaturas, como en el refrigerador, en un lugar fresco y a temperatura ambiente, y observa cómo cambia su aspecto y su duración.','Análisis','3 semanas',18,array['Temperatura','Conservación']::text[],array['investigar']::text[],'propios',NULL,'ingenieria alimentaria ingenieria agroindustrial nutricion ingenieria quimica quimica biologia diseno administracion medicion de temperatura. observacion. graficas. analisis. termometro, si es posible. alimentos de casa. hoja de calculo.',$a31agr${"id": "como-influye-la-temperatura-en-la-conservacion-de-los-alimentos", "area": "agricultura", "areas2": [], "titulo": "¿Cómo influye la temperatura en la conservación de los alimentos?", "resumen": "Guarda los mismos alimentos a distintas temperaturas, como en el refrigerador, en un lugar fresco y a temperatura ambiente, y observa cómo cambia su aspecto y su duración.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Temperatura", "Conservación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Alimentaria", "Ingeniería Agroindustrial", "Nutrición", "Ingeniería Química", "Química", "Biología", "Diseño", "Administración"], "problema": ["Se sabe que el frío alarga la vida de muchos alimentos, pero no todos reaccionan igual: algunos se dañan en el refrigerador. También se suele guardar en el sitio equivocado por comodidad.", "Observar el efecto de la temperatura ayuda a decidir dónde guardar cada alimento."], "desarrollar": ["Elige tres o cuatro alimentos frescos, como tomate, plátano, pan y zanahoria, y guarda porciones iguales en tres lugares con distinta temperatura. Anota la temperatura aproximada de cada lugar con un termómetro, si lo tienes.", "Revisa cada día el aspecto, la firmeza y el olor. Compara cuánto duró cada alimento en cada lugar y escribe una tabla de recomendación de dónde guardar cada uno."], "ampliaciones": [{"titulo": "Alimentos que sufren frío", "aporta": "identifica cuáles se dañan en el refrigerador."}, {"titulo": "Cuenta de energía", "aporta": "reflexiona sobre cuánto cuesta enfriar frente a guardar al ambiente."}, {"titulo": "Gráfica de duración", "aporta": "grafica la duración según la temperatura."}], "objetivos": ["Preparar muestras.", "Registrar la temperatura y el aspecto.", "Comparar resultados.", "Elaborar una tabla de recomendación."], "habilidades": ["Medición de temperatura.", "Observación.", "Gráficas.", "Análisis."], "herramientas": ["Termómetro, si es posible.", "Alimentos de casa.", "Hoja de cálculo."], "lineamientos": ["No pruebes ni consumas alimentos que parezcan echados a perder; el objetivo es observar, no arriesgarse.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No dejes a temperatura ambiente alimentos cocidos o de origen animal: es peligroso. Usa solo vegetales y panes."], "otroSector": "El mismo análisis del efecto de la temperatura sirve para estudiar cadenas de frío, almacenes o transporte de productos."}$a31agr$::jsonb,38),
('tecnicas-tradicionales-de-conservacion-funcionan-y-como-registra','agricultura',array['sociedad']::text[],'Técnicas tradicionales de conservación: ¿funcionan y cómo registrarlas?','Documenta cómo conservaban los alimentos tus abuelos o tu comunidad, como el secado o el salado, y averigua con fuentes confiables por qué funcionan, para valorar y registrar ese conocimiento.','Investigación','4 semanas',24,array['Saberes tradicionales','Conservación']::text[],array['investigar']::text[],'propios',NULL,'antropologia historia agronomia nutricion comunicaciones biologia sociologia diseno grafico entrevistas. registro cultural. busqueda de fuentes. redaccion. cuaderno o grabadora, con permiso. fuentes publicas. un editor de documentos.',$a32agr${"id": "tecnicas-tradicionales-de-conservacion-funcionan-y-como-registra", "area": "agricultura", "areas2": ["sociedad"], "titulo": "Técnicas tradicionales de conservación: ¿funcionan y cómo registrarlas?", "resumen": "Documenta cómo conservaban los alimentos tus abuelos o tu comunidad, como el secado o el salado, y averigua con fuentes confiables por qué funcionan, para valorar y registrar ese conocimiento.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Saberes tradicionales", "Conservación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Antropología", "Historia", "Agronomía", "Nutrición", "Comunicaciones", "Biología", "Sociología", "Diseño Gráfico"], "problema": ["Muchas técnicas de conservación, como secar al sol, ahumar o salar, nacieron mucho antes de los refrigeradores. Estos saberes se están perdiendo porque no se registran y se los considera anticuados.", "Documentarlos y explicar su lógica ayuda a valorarlos y a entender qué los hacía funcionar."], "desarrollar": ["Con permiso, conversa con una o dos personas mayores o con productores sobre cómo conservaban los alimentos. Anota qué alimentos, qué procesos y qué cuidados tenían. Luego busca en fuentes confiables por qué cada técnica ayuda a conservar, por ejemplo al quitar agua o al agregar sal.", "Escribe una ficha por cada técnica con su descripción, su explicación y sus límites. Reúnelas en un pequeño cuaderno de saberes con los nombres de quienes los compartieron, si ellos aceptan."], "ampliaciones": [{"titulo": "Comparar con lo actual", "aporta": "contrasta la técnica tradicional con un método moderno."}, {"titulo": "Registro en video o audio", "aporta": "graba un relato corto, con permiso, para conservarlo."}, {"titulo": "Mapa de técnicas", "aporta": "ubica en un mapa dónde se usa cada técnica."}], "objetivos": ["Conversar con permiso.", "Registrar cada técnica.", "Explicar por qué funciona.", "Reunir un cuaderno de saberes."], "habilidades": ["Entrevistas.", "Registro cultural.", "Búsqueda de fuentes.", "Redacción."], "herramientas": ["Cuaderno o grabadora, con permiso.", "Fuentes públicas.", "Un editor de documentos."], "lineamientos": ["Documenta saberes tradicionales con permiso y cita siempre a quien te los comparte; no los presentes como propios ni como recetas con fines médicos.", "Algunas conservas caseras, como las de frascos sin acidez, pueden ser peligrosas si se hacen mal: documéntalas pero no las presentes como instrucciones sin respaldo de fuentes oficiales.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados."], "otroSector": "El mismo registro de procesos y saberes sirve para documentar oficios y recetas de cualquier tradición."}$a32agr$::jsonb,39),
('menos-perdidas-durante-el-almacenamiento-y-el-transporte-de-alim','agricultura',array['negocios']::text[],'Menos pérdidas durante el almacenamiento y el transporte de alimentos','Investiga en qué momentos se dañan los alimentos mientras se almacenan y se transportan, y qué prácticas simples, como el empaque, la ventilación o la temperatura, reducen esas pérdidas.','Investigación','4 semanas',22,array['Pérdidas poscosecha','Transporte']::text[],array['investigar','resolver']::text[],'publicos',NULL,'logistica ingenieria agroindustrial ingenieria alimentaria ingenieria industrial administracion ingenieria de transporte estadistica diseno lectura de informes. clasificacion. analisis de causas. propuesta de mejoras. informes publicos. hoja de calculo. un diagrama de causas.',$a33agr${"id": "menos-perdidas-durante-el-almacenamiento-y-el-transporte-de-alim", "area": "agricultura", "areas2": ["negocios"], "titulo": "Menos pérdidas durante el almacenamiento y el transporte de alimentos", "resumen": "Investiga en qué momentos se dañan los alimentos mientras se almacenan y se transportan, y qué prácticas simples, como el empaque, la ventilación o la temperatura, reducen esas pérdidas.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 22, "etiquetas": ["Pérdidas poscosecha", "Transporte"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Logística", "Ingeniería Agroindustrial", "Ingeniería Alimentaria", "Ingeniería Industrial", "Administración", "Ingeniería de Transporte", "Estadística", "Diseño"], "problema": ["Un alimento no se pierde solo en el campo: también se golpea, se calienta o se aplasta mientras se guarda y se lleva al mercado. Estas pérdidas encarecen los productos y desperdician el esfuerzo del productor.", "Identificar dónde ocurren ayuda a proponer mejoras prácticas y de bajo costo."], "desarrollar": ["Con informes públicos de instituciones agrarias y de logística, identifica las causas más frecuentes de pérdida durante el almacenamiento y el transporte de dos o tres alimentos. Clasifícalas en golpes, calor, humedad, plagas y demoras.", "Para cada causa, reúne dos prácticas de mejora que mencionen las fuentes y organízalas en una tabla con su costo aproximado y su dificultad. Concluye con una lista de tres medidas que serían las más sencillas de aplicar."], "ampliaciones": [{"titulo": "Caso concreto", "aporta": "analiza el recorrido de un producto específico, como la papa o el tomate."}, {"titulo": "Costo de la pérdida", "aporta": "estima cuánto dinero se pierde por cada punto de pérdida."}, {"titulo": "Lista de verificación", "aporta": "crea una lista para que un productor revise su carga antes de enviarla."}], "objetivos": ["Identificar causas de pérdida.", "Clasificarlas.", "Reunir prácticas de mejora.", "Priorizar las más sencillas."], "habilidades": ["Lectura de informes.", "Clasificación.", "Análisis de causas.", "Propuesta de mejoras."], "herramientas": ["Informes públicos.", "Hoja de cálculo.", "Un diagrama de causas."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Presenta las medidas como ideas de mejora, no como instrucciones comerciales.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados."], "otroSector": "El mismo análisis de dónde se dañan los productos sirve para reducir mermas en el transporte de cualquier mercadería."}$a33agr$::jsonb,40)
